//! What the gate (admin, `save_as`) needs to know about a model, on the
//! SeaORM entity itself.
//!
//! A trait, not a second model. For a project's models it is generated by
//! `model!{}`, from the same source as the forms; Runique implements it by
//! hand for its own tables. Kept thin: display belongs to the builder.
use crate::utils::constants::resource_key;
use sea_orm::{ConnectionTrait, DbErr, EntityTrait, PrimaryKeyTrait, TransactionTrait};
use std::collections::HashMap;
use std::future::Future;
use std::str::FromStr;

/// `FromStr` on the key: a row's id arrives as URL text, each model parses it
/// with its own key type (`i32`, `Uuid`…). A composite key can't, so such a
/// table can't be registered: a compile error, not a runtime one.
pub trait ModelMeta:
    EntityTrait<Model: Sync, PrimaryKey: PrimaryKeyTrait<ValueType: Clone + PartialEq + Sync + FromStr>>
{
    /// Resource key, also the rights key in `eihwaz_groupes_droits`.
    const KEY: &'static str;
    /// Column holding the owner's id. Without one, `can_*_own` rights never
    /// open anything on this model.
    const OWNER: Option<Self::Column> = None;
    /// `eihwaz_users`: its superuser accounts are protected by the gate.
    const IS_ACCOUNT_TABLE: bool = false;
    /// Columns never shown, searched, filtered, sorted or written through the
    /// gate (a password hash). Even unshown, a searchable or sortable secret is an
    /// oracle: rows coming back for a guessed prefix give the value away.
    const SECRET: &'static [Self::Column] = &[];
    /// A table of Runique's own (accounts, groups, rights): its rights come
    /// from the rank, never from a group — a group granting itself rights on
    /// them would be a privilege escalation.
    const IS_FRAMEWORK_TABLE: bool = false;
    /// The model's form: generated by `model!{}` / `extend!{}` from the
    /// model's own fields (`{Model}ModelForm`). The admin builds its pages from
    /// it, unless the model is registered with `ModelAdmin::with_form`.
    type Form: crate::forms::field::RuniqueForm + crate::forms::FormEntity<Entity = Self>;
    /// The model's columns as the migration creates them: nullability;
    /// default, auto_now. The entity alone doesn't know a column's default.
    fn schema() -> crate::schema::ModelSchema;
    /// Column a row is known by in the history; its key when there is none.
    const LABEL: Option<Self::Column> = None;
    /// The model's list fields (`checkbox` / `multichoice`). Each has a table
    /// of its own and no column: the gate reaches them by these names, the
    /// ones their rights and their form fields carry.
    const LISTS: &'static [&'static str] = &[];
    /// Replaces, for `row`, each list field `values` names: its values
    /// comma-separated, as a form holds them; an empty text clears the list.
    /// A list `values` doesn't name is left as it is. Run in the transaction
    /// that writes `row`.
    fn save_lists<C>(
        row: &Self::Model,
        db: &C,
        values: &HashMap<String, String>,
    ) -> impl Future<Output = Result<(), DbErr>> + Send
    where
        C: ConnectionTrait + TransactionTrait,
    {
        let _ = (row, db, values);
        async { Ok(()) }
    }
    /// The values of the list fields of the row `key`, by name,
    /// comma-separated as a form holds them. By the key, not the row: the
    /// edit page reads only the columns its account may see.
    fn list_values<C>(
        key: <Self::PrimaryKey as PrimaryKeyTrait>::ValueType,
        db: &C,
    ) -> impl Future<Output = Result<Vec<(&'static str, String)>, DbErr>> + Send
    where
        C: ConnectionTrait,
    {
        let _ = (key, db);
        async { Ok(Vec::new()) }
    }
}

impl ModelMeta for crate::auth::user::Entity {
    const KEY: &'static str = resource_key::USERS;
    type Form = crate::auth::form::UserModelForm;
    const IS_ACCOUNT_TABLE: bool = true;
    const SECRET: &'static [Self::Column] = &[crate::auth::user::Column::Password];
    const IS_FRAMEWORK_TABLE: bool = true;
    const LABEL: Option<Self::Column> = Some(crate::auth::user::Column::Username);
    fn schema() -> crate::schema::ModelSchema {
        crate::auth::user::schema()
    }
}

/// The groups: their owner is their responsable, so a right "on its own"
/// reaches the groups an account answers for, and a new group is answered
/// for by whoever creates it.
impl ModelMeta for crate::auth::permissions::group::Entity {
    const KEY: &'static str = resource_key::GROUPES;
    type Form = crate::auth::form::GroupeModelForm;
    const OWNER: Option<Self::Column> =
        Some(crate::auth::permissions::group::Column::ResponsableId);
    const IS_FRAMEWORK_TABLE: bool = true;
    const LABEL: Option<Self::Column> = Some(crate::auth::permissions::group::Column::Nom);
    fn schema() -> crate::schema::ModelSchema {
        crate::auth::permissions::group::schema()
    }
}
